    private DiskChatStore OpenHistoryStore()
    {
        lock(gate) {
            string directory=Path.Combine(Path.GetDirectoryName(ConfigFile),"PhoneChatCache");
            Directory.CreateDirectory(directory);
            // Other running game processes have their own database and are never deleted.
            foreach(var file in Directory.EnumerateFiles(directory,"chat-*.db")) {
                if(!int.TryParse(Path.GetFileNameWithoutExtension(file)[5..],out var pid))continue;
                bool active;try{using var process=System.Diagnostics.Process.GetProcessById(pid);active=!process.HasExited;}catch{active=false;}
                if(active)continue;
                foreach(var suffix in new[]{"","-wal","-shm"})try{File.Delete(file+suffix);}catch{}
            }
            bool reset=!gameState.ContainsKey("diskHistory");
            var store=new DiskChatStore(Path.Combine(directory,"chat-"+Environment.ProcessId+".db"),reset);
            if(reset&&gameState.TryGetValue("records",out var legacy)&&legacy is List<string> records)
                foreach(var record in records)store.Add(JsonSerializer.Deserialize<ChatEntry>(record));
            if(!gameState.TryGetValue("sourceMode",out var mode)||(string)mode!="window-records-v1"){
                gameState["sourceMode"]="window-records-v1";gameState["historyVersion"]=Guid.NewGuid().ToString("N");
            }
            gameState.Remove("records");gameState.Remove("historyKeys");gameState["diskHistory"]=true;
            return store;
        }
    }
