    public PhoneChat()
    {
        try { if(File.Exists(ConfigFile)) settings=JsonSerializer.Deserialize<Settings>(File.ReadAllText(ConfigFile))??new(); } catch { }
        settings.Channels ??= new();settings.QQChannels??=new();
        settings.PushPriority=(settings.PushPriority??PushRouter.Order(settings.PushMode)).Select(p=>p>=0&&p<=3?p:0).Concat(new[]{0,0,0}).Take(3).ToArray();
        settings.PublicAddress ??= "";
        if(string.IsNullOrWhiteSpace(settings.ApkDownloadUrl))settings.ApkDownloadUrl="https://github.com/Xiao-Yanjiu/OmniToolbox.xiaoyanjiu/releases";
        try {
            using var config=JsonDocument.Parse(File.Exists(ConfigFile)?File.ReadAllText(ConfigFile):"{}");
            if(!config.RootElement.TryGetProperty("ExternalPort",out _)) {
                var legacy=settings.PublicAddress.Trim().TrimEnd('/');
                if(!legacy.StartsWith("https://",StringComparison.OrdinalIgnoreCase))legacy="https://"+legacy;
                settings.ExternalPort=Uri.TryCreate(legacy,UriKind.Absolute,out var oldUri)&&Regex.IsMatch(legacy,@":\d+$")?oldUri.Port:settings.Port;
                if(oldUri!=null)settings.PublicAddress=oldUri.Host;
            }
        } catch { }
        entries=OpenHistoryStore();RestorePairingFile();RestoreGameState();RestorePushKeys();RestoreQQSecrets();
    }
