        {
            if(await tls.ReadAsync(one,ct)==0)return;head.Add(one[0]);
            if(head.Count>=4&&head[^4]==13&&head[^3]==10&&head[^2]==13&&head[^1]==10)break;
        }
        if(head.Count>=8192)return;
        var lines=Encoding.ASCII.GetString(head.ToArray()).Split("\r\n");var first=lines[0].Split(' ');if(first.Length!=3)return;
