        lock(gate){if(listener==null&&PushRouter.Providers(PushConfiguration()).Length==0)return;var now=Environment.TickCount64;var key=channel+"|"+sender+"|"+target+"|"+text;
            foreach(var old in duplicate.Where(e=>now-e.Value>2000).Select(e=>e.Key).ToArray())duplicate.Remove(old);
            if(duplicate.ContainsKey(key))return;duplicate[key]=now;
