    private static Func<ushort,byte,byte,bool> BuildTabFilter(object config)
    {
        var type=config.GetType().Assembly.GetType("OmniToolbox.TreePublic.BetterChatFilters");
        var method=type?.GetMethod("Matches",BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic);
        if(method==null)throw new InvalidOperationException("Omni 窗口过滤接口不匹配");
        return (Func<ushort,byte,byte,bool>)method.CreateDelegate(typeof(Func<ushort,byte,byte,bool>),config);
    }
    private unsafe void RefreshGameMetadata()
    {
        var tabs=new List<PhoneTab>();var macros=new List<object>();string warning="";
        try
        {
            var log=RaptureLogModule.Instance();
            Func<ushort,byte,byte,bool>[] nativeFilters;
            try{nativeFilters=ReadNativeFilters();}catch(Exception e){warning="原生聊天过滤读取："+e.Message;nativeFilters=Enumerable.Range(0,4).Select(_=>(Func<ushort,byte,byte,bool>)((_,_,_)=>false)).ToArray();}
            if(log!=null)for(int i=0;i<4;i++)
            {
                string name=log->ChatTabs[i].Name.ToString();if(string.IsNullOrWhiteSpace(name))name=new[]{"通常","战斗","剧情","聊天4"}[i];
                
                tabs.Add(new PhoneTab{id="native:"+i,name=name,source="原生",filterSignature=nativeFilterSignature,recordSource="native",nativeWindow=true,filter=nativeFilters[i]});
            }
            var manager=FindOmniTreeHouseManager();
            var modules=manager?.GetType().GetProperty("Modules")?.GetValue(manager) as IEnumerable;
            if(modules!=null)foreach(var module in modules)
            {
                if(module==null||module.GetType().Name!="ChatFrameOptimization")continue;
                if(ReadValue(module.GetType(),module,"IsEnabled") is false)continue;
                var config=FirstFieldOfType(module,"ChatFrameOptimizationConfig");if(config==null)continue;
                var better=ReadValue(config.GetType(),config,"BetterChatTabs") as IEnumerable;if(better==null)continue;
                int extra=0;foreach(var tab in better)
                {
                    if(tab==null)continue;var type=tab.GetType();int native=ReadValue(type,tab,"NativeTabIndex") is int n?n:-1;
                    var nativeFilter=native>=0?tabs.FirstOrDefault(t=>t.id=="native:"+native)?.filter:null;
                    if(native>=0)tabs.RemoveAll(t=>t.id=="native:"+native);
                    if(ReadValue(type,tab,"Hidden") is true)continue;
                    var kinds=(ReadValue(type,tab,"ChatTypes") as IEnumerable)?.Cast<object>().Select(Convert.ToUInt16).ToArray()??Array.Empty<ushort>();
                    tabs.Add(new PhoneTab{id=native>=0?"native:"+native:"omni:"+(extra++),name=ReadMember(type,tab,"Name"),source="Omni",filterSignature=JsonSerializer.Serialize(new{kinds,rows=ReadValue(type,tab,"FilterRows")}),recordSource=ReadValue(type,tab,"IsOmniWorldChannel") is true?"omni-world":"omni-native",nativeWindow=false,filter=BuildTabFilter(tab),kinds=kinds,world=ReadValue(type,tab,"IsOmniWorldChannel") is true});
                }
                break;
            }
            var macroModule=RaptureMacroModule.Instance();
            if(macroModule!=null&&settings.AllowCommands)for(uint set=0;set<2;set++)for(uint index=0;index<100;index++)
            {var macro=macroModule->GetMacro(set,index);if(macro==null||!macro->IsNotEmpty())continue;macros.Add(new{set,index,name=macro->Name.ToString(),lines=string.Join("\n",macro->Lines.ToArray().Select(l=>l.ToString()))});}
            var novice=InfoProxyNoviceNetwork.Instance();noviceJoined=novice!=null&&novice->IsInNoviceNetwork;
            var client=worldClient??FindOmniWorldChatClient();worldJoined=client!=null&&ReadValue(client.GetType(),client,"Connected") is true;
            if(settings.AllowCommands&&phoneCommands.Length==0)
            {
                var commands=new List<object>();var data=GetService<IDataManager>("Dalamud.Data.DataManager");
                var sheet=data?.GetExcelSheet<Lumina.Excel.Sheets.TextCommand>();
                if(sheet!=null)foreach(var command in sheet)
                {string name=command.Command.ToString();if(name.StartsWith('/'))commands.Add(new{name,description=command.Description.ToString(),alias=string.Join(" ",new[]{command.Alias.ToString(),command.ShortAlias.ToString(),command.ShortCommand.ToString()}),group="system"});}
                if(DalamudServices.CommandManager!=null)foreach(var command in DalamudServices.CommandManager.Commands)commands.Add(new{name=command.Key,description=command.Value.HelpMessage,alias="",group="plugin"});
                lock(gate)phoneCommands=commands.ToArray();
            }
        }
        catch(Exception e){warning="聊天配置读取："+e.Message;}
        lock(gate)
        {
            try{phoneChannelInfo=ReadGameChannelNames();}catch(Exception e){warning="通讯贝名称读取："+e.Message;}
            phoneTabs=tabs.ToArray();phoneMacros=macros.ToArray();metadataError=string.Join("；",new[]{warning,sourceError}.Where(v=>v.Length>0));
            string signature=JsonSerializer.Serialize(new{tabs=phoneTabs,macros=phoneMacros,commands=phoneCommands,channelInfo=phoneChannelInfo,worldJoined,noviceJoined,warning,nativeFilterSignature,routes=entries.Recent(400).Select(e=>new{e.id,tabs=MatchEntryTabs(e)})});
            if(signature!=metadataSignature){metadataSignature=signature;metadataRevision++;}
            string filters=JsonSerializer.Serialize(phoneTabs.Select(t=>new{t.id,t.recordSource,t.world,t.filterSignature}));if(filters!=windowFilterSignature){windowFilterSignature=filters;nativeHistoryCursor=-1;historyScan.Clear();historyRequested=true;}
        }
    }
    private static unsafe object[] ReadGameChannelNames()
    {
        var names=new List<object>();
        var linkshell=InfoProxyLinkshell.Instance();var cross=InfoProxyCrossWorldLinkshell.Instance();
        for(int i=0;i<8;i++)
        {
            string name="";
            if(linkshell!=null&&linkshell->LinkShells[i].Id!=0)name=linkshell->GetLinkshellName(linkshell->LinkShells[i].Id).ToString();
            names.Add(new{id="通讯贝"+(i+1),name=name,group="linkshell",slot=i+1,available=!string.IsNullOrWhiteSpace(name)});
            string crossName=cross!=null?cross->CrossWorldLinkshells[i].Name.ToString():"";
            names.Add(new{id="跨服贝"+(i+1),name=crossName,group="crossworld",slot=i+1,available=!string.IsNullOrWhiteSpace(crossName)});
        }
        return names.ToArray();
    }
    private void AttachWorld()
    {
        if(worldClient!=null)return;var client=FindOmniWorldChatClient();if(client==null)return;
        try
        {
            worldClient=client;
            foreach(var name in new[]{"MessageReceived","WhisperReceived"})
            {
                var evt=client.GetType().GetEvent(name);var type=client.GetType().GetNestedType(name=="MessageReceived"?"ChannelMessage":"ChannelWhisper",BindingFlags.Public|BindingFlags.NonPublic);
                if(evt==null||type==null)continue;
                var handler=(Delegate)GetType().GetMethod(nameof(Hook),BindingFlags.Instance|BindingFlags.NonPublic).MakeGenericMethod(type).Invoke(this,new object[]{client,evt,name=="WhisperReceived"});hooks.Add((evt,handler));
            }
        }catch{DetachWorld();}
    }
    private Delegate Hook<T>(object client,EventInfo evt,bool whisper)
    {Action<T> action=message=>World(message,whisper);evt.AddEventHandler(client,action);return action;}
    private void DetachWorld(){foreach(var hook in hooks)try{hook.evt.RemoveEventHandler(worldClient,hook.handler);}catch{}hooks.Clear();worldClient=null;}
    private void World(object message,bool whisper)
    {
        if(message==null||worldClient==null)return;var type=message.GetType();var self=ReadValue(worldClient.GetType(),worldClient,"SelfAliasID");
        if(self is not int me||me<=0)return;
        if(whisper)
        {
            if(ReadValue(type,message,"RecipientAliasID") is int recipient&&recipient==me&&ReadValue(type,message,"SenderAliasID") is int sender)
                Add("国服悄悄话",ReadMember(type,message,"SenderDisplayName"),sender.ToString(),ReadMember(type,message,"Text"),false,settings.ReceiveWorldWhisper);
            else if(ReadValue(type,message,"SenderAliasID") is int senderId&&senderId==me&&ReadValue(type,message,"RecipientAliasID") is int dest)
                Add("国服悄悄话","我",dest.ToString(),ReadMember(type,message,"Text"),true);
            return;
        }
        var mention=ReadValue(type,message,"Mention");bool notify=mention!=null&&ReadValue(mention.GetType(),mention,"AliasID") is int id&&id==me&&settings.NotifyMention;
        bool outgoing=ReadValue(type,message,"AliasID") is int senderAlias&&senderAlias==me;
        // Sender AliasID is exposed separately so phone can @ or whisper without guessing a name.
        var alias=ReadValue(type,message,"AliasID")?.ToString()??"";
        if(notify)Add("国服",WorldSender(message),alias,ReadMember(type,message,"Text"),false,true);else historyRequested=true;
    }
